import hashlib
import json
import re
import sys
from urllib.parse import urlparse

ALLOWED_CHECKSUM_ALGOS = {
    "SHA1", "SHA256", "SHA512", "MD5", "SHA3-256", "SHA3-384", "SHA3-512",
