    "AFFECTS", "AMENDS", "ANCESTOR_OF", "BUILD_DEPENDENCY_OF", "BUILD_TOOL_OF",
    "CONTAINED_BY", "CONTAINS", "COPIED_TO", "DATA_FILE_OF", "DEPENDENCY_OF",
    "DEPENDS_ON", "DESCENDANT_OF", "DESCRIBED_BY", "DESCRIBES",
    "DEV_DEPENDENCY_OF", "DEV_TOOL_OF", "DISTRIBUTION_ARTIFACT",
    "DOCUMENTATION_OF", "DYNAMIC_LINK", "EXAMPLE_OF", "EXPANDED_FROM_ARCHIVE",
